body.script:
//
					const cfg      = document.getElementById('cfg').dataset;
					const ASSET    = cfg.asset;
					// "Timeframe" dropdown — same options as /4l/<asset>'s own
					// dropdown (see TF_WINDOW below for the per-timeframe
					// visible-window convention it shares with those pages),
					// but 1d default here, an independent product decision
					// from that page's own 15m default.
					let INTERVAL = '1d';
					// Deribit perpetual futures, same symbol convention
					// /gt/<asset> and /4l/<asset> use (server-side
					// _DERIBIT_PERPETUAL_SYMBOL_MAP).
					const DERIBIT_PERP_SYMBOL = { BTC: 'BTC-PERPETUAL', ETH: 'ETH-PERPETUAL' }[ASSET] || (ASSET + '-PERPETUAL');
					document.getElementById('exchange-label').textContent = 'Deribit · ' + DERIBIT_PERP_SYMBOL;
					const klineUrl = (iv, limit) => '/api/klines-futures/' + ASSET + '?interval=' + iv + '&limit=' + limit;
					// "Expiry" dropdown — which expiry's trades feed the 4
					// gamma legs, "all" default (was "weekly" until a later
					// product decision moved it). Unlike /4l/<asset>'s own
					// Nearest/Nearest+1/Nearest+2 (isolated to one exact
					// instrument), the server resolves this to the
					// configured weekly_expiry/monthly_expiry instrument and
					// computes CUMULATIVE through it — see mwa_gamma_json.
					// "all" skips that lookup and considers every one of
					// the asset's own non-expired instruments. Bookmarkable
					// via ?e=w/m/a on the page URL itself (resolved
					// server-side into cfg.initialExpiry — see
					// mwa_gamma_chart's own docstring); falls back to
					// 'all' for a missing/invalid ?e=, same as the
					// <select>'s own un-queried default.
					let EXPIRY_MODE = cfg.initialExpiry || 'all';
					// "Window" dropdown — trailing-hours trade window fed
					// into that same cumulative domain, independent of
					// EXPIRY_MODE. Choice set (12h/24h/48h/All), own independent
					// choice set from /4l/<asset>'s own "Window" dropdown —
					// 1h/2h/4h/6h/8h were removed per product decision,
					// which is also when the default moved from 4h to
					// "All" here; 2h was then re-added per a still later
					// product decision and made the new default, then
					// the default moved to 24h per a still later
					// product decision; 2h was then removed and 48h added
					// in its place per a still later product decision,
					// default staying 24h.
					// WINDOW_HOURS is the string 'all' when
					// "All" is selected (?hours=all, skipping the
					// trailing-hours trade filter entirely — see
					// mwa_gamma_json), a number otherwise.
					let WINDOW_HOURS = 24;
					const mwaGammaUrl = () => '/api/mwa-gamma/' + ASSET + '?expiry=' + EXPIRY_MODE + '&hours=' + WINDOW_HOURS;
					// Same "Last trade:" footer field the Delta Chart/gt/4l
					// pages use — a growing gap between this and "now" is
					// the at-a-glance signal that dankbit_ws has stalled
					// (its DB connection can die without crashing the
					// container, silently dropping every trade — see
					// dankbit_ws_batch.py).
					const LAST_TRADE_URL = '/api/last-trade/' + ASSET;
					let   lastTradeTs = null;
					// Trade count for the currently selected Window/Expiry —
					// same `trade_count` field /api/mwa-gamma already returns
					// (len(trades) over the resolved cumulative domain), same
					// convention /4l/<asset>'s own tradeCount uses. null until
					// the first refreshMwaGamma() resolves.
					let   tradeCount = null;

					// Shown in real UTC (not a browser-local shift) — this is a
					// staleness check against server time, not a chart position.
					function formatLastTradeTs(iso) {
						if (!iso) return null;
						return new Date(iso).toLocaleString('de-DE', {
							timeZone: 'UTC',
							year: 'numeric', month: '2-digit', day: '2-digit',
							hour: '2-digit', minute: '2-digit', second: '2-digit',
						}) + ' UTC';
					}

					// Same browser-local-timezone shift every other TV chart page
					// in this addon applies — Lightweight Charts always renders
					// epoch seconds as UTC wall-clock time, so every timestamp fed
					// into the chart is pre-shifted by the viewer's own current
					// UTC offset first.
					const tzOffset = (() => {
						let zone;
						try {
							zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
						} catch (e) {
							return 0;
						}
						const d = new Date();
						const utc = new Date(d.toLocaleString('en-US', { timeZone: 'UTC' }));
						const local = new Date(d.toLocaleString('en-US', { timeZone: zone }));
						return (local - utc) / 1000;
					})();

					const THEME_STORAGE_KEY = 'dankbit_theme';
					let DARK_MODE = localStorage.getItem(THEME_STORAGE_KEY) === 'dark';
					function rulerColor() { return DARK_MODE ? '#aaaaaa' : '#555555'; }
					// Black would vanish into the dark-mode chart background
					// (#000000), so LC/LP swap to a lighter gray there, same
					// axisBlack()-style convention every other "plain black"
					// line in this addon already uses (see
					// dankbit_templates.xml / four_leg_gamma_chart_templates.xml).
					function axisBlack() { return DARK_MODE ? '#e8e8e8' : '#000000'; }
					// Same per-leg color convention /4l/<asset> uses — LC/LP
					// both black (via axisBlack()), SC/SP both orange, per
					// product decision, not distinct hues per leg.
					const SCG_COLOR = '#fb8c00'; // Seller Call Gamma — orange
					const SPG_COLOR = '#fb8c00'; // Seller Put Gamma — orange
					const AVG_GAMMA_COLOR = '#bdbdbd'; // Average of LC/LP/SC/SP prices — light gray
					document.getElementById('theme-select').value = DARK_MODE ? 'dark' : 'light';
					document.body.classList.toggle('dark', DARK_MODE);

					const chart = LightweightCharts.createChart(document.getElementById('chart-container'), {
						width: window.innerWidth, height: window.innerHeight,
						layout: {
							background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
							textColor: DARK_MODE ? '#d1d4dc' : '#333333',
						},
						grid: { vertLines: { visible: false }, horzLines: { visible: false } },
						crosshair: { mode: LightweightCharts.CrosshairMode.Normal, horzLine: { labelBackgroundColor: 'blue' } },
						rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc', timeVisible: true, secondsVisible: false },
						localization: {
							timeFormatter: ts => new Date(ts * 1000).toLocaleString('de-DE', {
								timeZone: 'UTC',
								month: 'short', day: 'numeric',
								hour: '2-digit', minute: '2-digit',
							}),
						},
					});

					window.addEventListener('resize', () => {
						chart.resize(window.innerWidth, window.innerHeight);
					});

					const series = chart.addCandlestickSeries({
						upColor: '#26a69a', downColor: '#ef5350',
						borderVisible: false, wickUpColor: '#26a69a', wickDownColor: '#ef5350',
					});

					// Invisible helper series solely to extend the shared time
					// axis past the last real candle, same mechanism the Delta
					// Chart's own futureAxisSeries uses (dankbit_templates.xml)
					// and /4l/<asset>'s own copy — candlestick setData()
					// silently drops OHLC-less "whitespace" points, so a real,
					// fully-valued (if invisible) line series is used instead;
					// all series on a chart share one time scale, so its
					// future points extend the same axis the candlesticks and
					// the 5 gamma price lines are drawn on, leaving room to
					// see those lines extend forward instead of ending flush
					// at the last bar.
					const futureAxisSeries = chart.addLineSeries({
						color: 'rgba(0,0,0,0)', lineWidth: 1,
						lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});

					// The 4 gamma "lines" are horizontal reference lines at the
					// CURRENT (latest) value only — same createPriceLine()
					// pattern /gt/<asset> and /4l/<asset> use for their own
					// gamma lines — not a connected historical time series.
					// Redrawn on init and on any manual Timeframe/Expiry/
					// Window change, each replacing its own previous line
					// rather than accumulating one per hour — unlike every
					// other TradingView page in this addon, this one does
					// NOT auto-refresh on a timer: /api/mwa-gamma recomputes
					// options.per_leg_greeks() fresh server-side over a
					// cumulative multi-instrument trade set on every call,
					// which is too heavy to poll on dankbit.refresh_interval
					// unattended. Only the candle series keeps its own
					// normal 5s TradingView refresh (see init() below).
					let bcgPriceLine = null, bpgPriceLine = null, scgPriceLine = null, spgPriceLine = null, avgGammaPriceLine = null;

					function setStatus(text) { document.getElementById('status').textContent = text; }

					function lastTradeSuffix() {
						const label = formatLastTradeTs(lastTradeTs);
						return label ? '  ·  Last trade: ' + label : '';
					}

					// Same "N trades" convention /4l/<asset>'s own footer
					// uses — placed after the "Last trade:" timestamp since
					// it's the count feeding the same Window that
					// timestamp's own staleness matters for.
					function tradeCountSuffix() {
						return tradeCount !== null ? '  ·  ' + tradeCount + ' trades' : '';
					}

					function statusText() {
						const expiryLabel = EXPIRY_MODE === 'monthly' ? 'Monthly' : (EXPIRY_MODE === 'all' ? 'All' : 'Weekly');
						const windowLabel = WINDOW_HOURS === 'all' ? 'all trades' : (WINDOW_HOURS + 'h trailing window');
						return ASSET + ' · MWA Gamma (' + expiryLabel + ', ' + windowLabel + ', live)' + lastTradeSuffix() + tradeCountSuffix();
					}

					async function refreshLastTrade() {
						const data = await (await fetch(LAST_TRADE_URL)).json();
						lastTradeTs = data.last_trade_ts || null;
						setStatus(statusText());
					}

					function showSpinner() { document.getElementById('spinner').style.display = 'block'; }
					function hideSpinner() { document.getElementById('spinner').style.display = 'none'; }

					function toCandle(k) {
						return { time: Math.floor(k.t / 1000) + tzOffset, open: parseFloat(k.o), high: parseFloat(k.h), low: parseFloat(k.l), close: parseFloat(k.c) };
					}

					let realCandles = [];

					// Same per-timeframe visible-window convention the
					// Delta/Gamma/Strike Gamma/4l charts' own TF_WINDOW uses
					// (15m entry matches /gt/<asset>'s and /4l/<asset>'s own
					// TF_WINDOW).
					const TF_WINDOW = { '15m': 5, '1h': 30, '4h': 15, '1d': 365 };
					// Seconds per bar at each Timeframe — feeds the future-axis
					// tick spacing below (INTERVAL_SECONDS isn't needed
					// anywhere else on this page, unlike the Delta Chart's own
					// copy, which also uses it for its logical-range math).
					const INTERVAL_SECONDS = { '15m': 15 * 60, '1h': 3600, '4h': 4 * 3600, '1d': 86400 };
					// Same future-margin length as the Delta Chart's own
					// FUTURE_MARGIN_DAYS.
					const FUTURE_MARGIN_DAYS = 5;

					function applyVisibleRange() {
						if (!realCandles.length) return;
						const days = TF_WINDOW[INTERVAL] || 15;
						// Ends at the future-axis edge (see futureAxisSeries
						// above), not at the last real candle, so the visible
						// window always includes the future margin rather than
						// leaving it just off-screen to the right.
						const futureEdge = realCandles[realCandles.length - 1].time + FUTURE_MARGIN_DAYS * 86400;
						chart.timeScale().setVisibleRange({ from: futureEdge - days * 86400, to: futureEdge });
					}

					// Rebuilds both the real candle series and the invisible
					// future-axis extension together, so the two never fall
					// out of sync (same pattern the Delta Chart's own
					// rebuildSeriesData() uses).
					function rebuildSeriesData() {
						series.setData(realCandles);

						const intervalSec = INTERVAL_SECONDS[INTERVAL] || 3600;
						const lastClose = realCandles.length ? realCandles[realCandles.length - 1].close : 0;
						const lastTime = realCandles.length
							? realCandles[realCandles.length - 1].time
							: (Math.floor(Date.now() / 1000) + tzOffset);
						const count = Math.round(FUTURE_MARGIN_DAYS * 86400 / intervalSec);
						const futureTicks = [];
						for (let i = 1; i <= count; i++) {
							futureTicks.push({ time: lastTime + i * intervalSec, value: lastClose });
						}
						futureAxisSeries.setData(futureTicks);
					}

					function resetChartView() {
						chart.priceScale('right').applyOptions({ autoScale: true });
						applyVisibleRange();
					}

					const contextMenu = document.getElementById('context-menu');

					function hideContextMenu() {
						contextMenu.style.display = 'none';
					}

					function showContextMenu(x, y) {
						contextMenu.style.display = 'block';
						const maxX = window.innerWidth - contextMenu.offsetWidth - 4;
						const maxY = window.innerHeight - contextMenu.offsetHeight - 4;
						contextMenu.style.left = Math.min(x, maxX) + 'px';
						contextMenu.style.top = Math.min(y, maxY) + 'px';
					}

					function onResetChartViewClick() {
						resetChartView();
						hideContextMenu();
					}

					const chartContainerEl = document.getElementById('chart-container');
					chartContainerEl.addEventListener('contextmenu', e => {
						e.preventDefault();
						showContextMenu(e.clientX, e.clientY);
					});
					document.addEventListener('contextmenu', e => {
						if (!chartContainerEl.contains(e.target)) hideContextMenu();
					});
					document.addEventListener('click', hideContextMenu);
					window.addEventListener('resize', hideContextMenu);
					window.addEventListener('scroll', hideContextMenu, true);

					async function loadCandles() {
						const resp = await (await fetch(klineUrl(INTERVAL, 500))).json();
						const klines = (resp.result || []).slice().reverse();
						realCandles = klines.map(toCandle);
						rebuildSeriesData();
						applyVisibleRange();
					}

					async function updateLatestCandle() {
						const resp = await (await fetch(klineUrl(INTERVAL, 2))).json();
						const klines = resp.result || [];
						if (!klines.length) return;
						const updated = toCandle(klines[0]);
						if (realCandles.length && realCandles[realCandles.length - 1].time === updated.time) {
							realCandles[realCandles.length - 1] = updated;
						} else {
							realCandles.push(updated);
						}
						rebuildSeriesData();
					}

					async function setTf(iv) {
						INTERVAL = iv;
						await loadCandles();
					}

					async function setExpiry(mode) {
						EXPIRY_MODE = mode;
						await refreshMwaGamma();
						setStatus(statusText());
					}

					async function setWindow(hours) {
						WINDOW_HOURS = hours === 'all' ? 'all' : parseInt(hours, 10);
						await refreshMwaGamma();
						setStatus(statusText());
					}

					// Rounds and abbreviates large raw dollar-gamma values
					// (hundreds of millions to billions is typical here) —
					// thousands as K, millions as M, sign preserved (long
					// legs' gamma is positive, short legs' is negative, per
					// this addon's own convention — see per_leg_greeks).
					function formatAbbreviated(value) {
						const sign = value < 0 ? '-' : '';
						const abs = Math.abs(value);
						if (abs >= 1e6) return sign + Math.round(abs / 1e6) + 'M';
						if (abs >= 1e3) return sign + Math.round(abs / 1e3) + 'K';
						return sign + Math.round(abs);
					}

					// Only the LATEST reading is used — /api/mwa-gamma has no
					// persisted history (nothing is ever written server-side
					// for this page), so this just draws a horizontal line
					// at each leg's own current value.
					//
					// Shows #spinner for the duration of the fetch — this
					// endpoint recomputes the 4-leg gamma curve fresh
					// server-side on every call, over a cumulative
					// multi-instrument trade set (can be noticeably slower
					// than /4l/<asset>'s own single-instrument version).
					// Hidden in a finally so a fetch error still clears it
					// rather than leaving it spinning forever — same pattern
					// /gt's and /4l's own refresh functions use.
					async function refreshMwaGamma() {
						showSpinner();
						try {
							const data = await (await fetch(mwaGammaUrl())).json();
							const points = data.points || [];
							const latest = points.length ? points[points.length - 1] : null;

							// 0 (not null) once resolved with no trades at all in
							// the current Window/Expiry — null only ever means
							// "haven't fetched yet", so tradeCountSuffix() can
							// tell "0 trades" apart from "not loaded" (same
							// convention /4l/<asset>'s own refreshFourLegGamma()
							// uses).
							tradeCount = latest ? latest.trade_count : 0;
							setStatus(statusText());

							if (bcgPriceLine) { series.removePriceLine(bcgPriceLine); bcgPriceLine = null; }
							if (bpgPriceLine) { series.removePriceLine(bpgPriceLine); bpgPriceLine = null; }
							if (scgPriceLine) { series.removePriceLine(scgPriceLine); scgPriceLine = null; }
							if (spgPriceLine) { series.removePriceLine(spgPriceLine); spgPriceLine = null; }
							if (avgGammaPriceLine) { series.removePriceLine(avgGammaPriceLine); avgGammaPriceLine = null; }
							if (!latest) return;

							// 0.0 means absent (same convention every
							// gamma_band/smart_liq_*_price field in this addon
							// uses) — no line drawn rather than a spurious
							// price-0 line. axisLabelColor matches each
							// line's own color here (unlike most other price
							// lines in this addon, which force a black axis
							// label regardless of line color) so the label is
							// identifiable by color at a glance with 4 lines
							// on one chart — except LC/LP, which are
							// deliberately both black (axisBlack(), theme-
							// aware) per product decision, so their axis
							// labels match each other instead of standing
							// apart.
							if (latest.bcg_price) {
								bcgPriceLine = series.createPriceLine({
									price: latest.bcg_price, color: axisBlack(), lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: axisBlack(),
									title: 'LC ' + formatAbbreviated(latest.bcg_value),
								});
							}
							if (latest.bpg_price) {
								bpgPriceLine = series.createPriceLine({
									price: latest.bpg_price, color: axisBlack(), lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: axisBlack(),
									title: 'LP ' + formatAbbreviated(latest.bpg_value),
								});
							}
							if (latest.scg_price) {
								scgPriceLine = series.createPriceLine({
									price: latest.scg_price, color: SCG_COLOR, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: SCG_COLOR,
									title: 'SC ' + formatAbbreviated(latest.scg_value),
								});
							}
							if (latest.spg_price) {
								spgPriceLine = series.createPriceLine({
									price: latest.spg_price, color: SPG_COLOR, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: SPG_COLOR,
									title: 'SP ' + formatAbbreviated(latest.spg_value),
								});
							}
							// Average of the legs' own gamma PRICE levels (not
							// their gamma value) — over whichever legs are
							// actually present (0.0 means absent, see above),
							// not a fixed /4, since dividing a partial sum by 4
							// would silently skew the average toward 0 for
							// every missing leg. Skipped only when none of the
							// 4 are present at all. The label additionally
							// shows the average of those same legs' own gamma
							// VALUES (paired with price so both are averaged
							// over the identical present-leg set), same
							// formatAbbreviated() the other 4 lines already
							// use for their own value.
							const gammaLegs = [
								{ price: latest.bcg_price, value: latest.bcg_value },
								{ price: latest.bpg_price, value: latest.bpg_value },
								{ price: latest.scg_price, value: latest.scg_value },
								{ price: latest.spg_price, value: latest.spg_value },
							].filter(leg => leg.price);
							if (gammaLegs.length) {
								const avgGammaPrice = gammaLegs.reduce((a, leg) => a + leg.price, 0) / gammaLegs.length;
								const avgGammaValue = gammaLegs.reduce((a, leg) => a + leg.value, 0) / gammaLegs.length;
								avgGammaPriceLine = series.createPriceLine({
									price: avgGammaPrice, color: AVG_GAMMA_COLOR, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: AVG_GAMMA_COLOR,
									title: 'AVG ' + formatAbbreviated(avgGammaValue),
								});
							}
						} finally {
							hideSpinner();
						}
					}

					function applyTheme() {
						document.body.classList.toggle('dark', DARK_MODE);
						chart.applyOptions({
							layout: {
								background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
								textColor: DARK_MODE ? '#d1d4dc' : '#333333',
							},
							rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
							timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						});
					}

					function onThemeChange() {
						DARK_MODE = document.getElementById('theme-select').value === 'dark';
						localStorage.setItem(THEME_STORAGE_KEY, DARK_MODE ? 'dark' : 'light');
						applyTheme();
					}

					let rulerActive = false;
					let rulerPrice1 = null;
					let rulerLines  = [];

					function toggleRuler() {
						rulerActive = !rulerActive;
						document.getElementById('ruler-btn').classList.toggle('active', rulerActive);
						rulerLines.forEach(l => series.removePriceLine(l));
						rulerLines = [];
						rulerPrice1 = null;
						const info = document.getElementById('ruler-info');
						info.style.display = 'none';
						info.textContent = '';
					}

					chart.subscribeClick(param => {
						if (!rulerActive || !param.point) return;
						const price = series.coordinateToPrice(param.point.y);
						if (rulerPrice1 === null) {
							rulerPrice1 = price;
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '①',
							}));
						} else {
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '②',
							}));
							const pct = ((price - rulerPrice1) / rulerPrice1 * 100);
							const sign = pct >= 0 ? '+' : '';
							const info = document.getElementById('ruler-info');
							info.style.display = 'block';
							info.textContent = rulerPrice1.toFixed(0) + ' → ' + price.toFixed(0) + '   ' + sign + pct.toFixed(2) + '%';
							rulerPrice1 = null;
						}
					});

					async function init() {
						try {
							// Sync the <select> to EXPIRY_MODE (which may have
							// come from ?e= rather than the element's own
							// statically-marked "all" default) before the
							// first fetch.
							document.getElementById('expiry-select').value = EXPIRY_MODE;
							await loadCandles();
							await refreshMwaGamma();
							await refreshLastTrade();
							setStatus(statusText());
						}
						catch (e) { setStatus('Error: ' + e.message); }
					}
					init();
					// Only the candle series auto-refreshes on a timer (TradingView's
					// own normal live-candle behavior). refreshMwaGamma()/
					// refreshLastTrade() run once here on load and again on any
					// manual Timeframe/Expiry/Window change (setTf/setExpiry/
					// setWindow below), but are deliberately NOT polled — this
					// page's gamma computation is too heavy (a fresh
					// options.per_leg_greeks() over a cumulative multi-instrument
					// trade set on every call) to re-run unattended on
					// dankbit.refresh_interval.
					setInterval(updateLatestCandle, 5000);
				//
